-- Dört bayi paketi: Ücretsiz, Pro, Plus, Özel (özellikler, modüller ve sınırlar). 999999 ve üzeri sınır = sınırsız.
-- Yönetici paneli Yazılım Paketleri'nde değiştirilen değerler korunur (INSERT IGNORE). Eski paketler satışta gösterilmez, mevcut abonelikleri çalışmaya devam eder.
UPDATE clinic_package_settings SET settings=JSON_SET(settings,'$.published',false) WHERE plan_id IN ('baslangic','profesyonel','kurumsal');
